import { useParams } from "react-router-dom";
import projects from "../data/projects";

const ProjectPage = () => {

    const { slug } = useParams();

    const project = projects.find(
        (item) => item.slug === slug
    );

    if (!project) {
        return <h1>Project Not Found</h1>;
    }

    return (

        <section>

            <h1>{project.title}</h1>

            <img
                src={project.image}
                alt={project.alt}
            />

            <p>{project.type}</p>

            <p>{project.with}</p>

        </section>

    );

};

export default ProjectPage;
